-- expand: the team card's links CHECK again, at twelve rather than six (§491, growing §474) — the ceiling of an event's own links (§332) and of the rows a save reads (§483). Migration 0093 dropped the six-link version; every stored list holds at most six, so none is refused by this one.
ALTER TABLE "team_members" ADD CONSTRAINT "team_members_links_is_a_short_array_of_https_links" CHECK ("team_members"."links" IS NULL OR CASE WHEN jsonb_typeof("team_members"."links") = 'array' THEN jsonb_array_length("team_members"."links") <= 12 AND NOT jsonb_path_exists("team_members"."links", '$[*] ? (!(@.url.type() == "string" && @.url starts with "https://"))') ELSE false END);
